const std = @import("std");
const compiler = @import("compiler");

pub fn main(init: std.process.Init) !void {
    const allocator = init.arena.allocator();
    const args = try init.minimal.args.toSlice(allocator);
    const mode = args[1];
    const sources = try @import("fixture.zig").sources(mode);

    var decoded = block: {
        var analysis = try compiler.project.analyze(std.heap.page_allocator, &sources, .{
            .entry = "main.zx",
            .root_dir = "/project",
            .native_interfaces = if (std.mem.eql(u8, mode, "effects")) &.{.{ .specifier = "zig:probe", .path = "interface.d.zx", .source = @embedFile("fixtures/interface.d.zx"), .module = "probe" }} else &.{},
        });

        defer analysis.deinit();

        if (analysis.value == .diagnostic) {
            std.debug.print("{s}: {t}: {s}\n", .{ mode, analysis.value.diagnostic.code, analysis.value.diagnostic.message });

            return error.InvalidAnalysis;
        }

        try emit(init, analysis.value.ir, mode, args[2..4]);

        var library = try compiler.library.link(std.heap.page_allocator, &.{.{ .name = "run", .analysis = &analysis }});

        defer library.deinit();

        const bytes = try compiler.library.codec.encode(std.heap.page_allocator, &library);

        defer std.heap.page_allocator.free(bytes);

        const result = try compiler.library.codec.decode(allocator, bytes);

        @memset(bytes, 0);

        break :block result;
    };

    defer decoded.deinit();

    try emit(init, try decoded.module(0), mode, args[4..6]);
}

fn emit(init: std.process.Init, program: compiler.ir.Program, mode: []const u8, paths: []const []const u8) !void {
    const allocator = init.arena.allocator();

    if (try compiler.validateIr(allocator, program) != null) return error.InvalidIr;

    const bundle = try compiler.zig.emitBundle(allocator, program);

    defer bundle.deinit(allocator);

    try @import("shape.zig").check(bundle.source, mode);
    try std.Io.Dir.cwd().writeFile(init.io, .{ .sub_path = paths[0], .data = bundle.source });
    try std.Io.Dir.cwd().writeFile(init.io, .{ .sub_path = paths[1], .data = bundle.types });
}

const std = @import("std");

pub fn check(source: []const u8, mode: []const u8) !void {
    const start = std.mem.indexOf(u8, source, "pub fn execute(") orelse return error.MissingExecute;
    const execute = source[start..];
    const loops = std.mem.count(u8, execute, "while (");
    const escaping = std.mem.eql(u8, mode, "escaping");
    const nested = std.mem.eql(u8, mode, "nested");

    if (loops == 0) return error.MissingLoop;

    if (escaping) {
        if (std.mem.indexOf(u8, execute, "function_") == null) return error.MissingEscapingHelper;

        return;
    }

    if (!nested and std.mem.indexOf(u8, execute, "function_") != null) return error.RemainingAggregateHelper;
    if (!std.mem.eql(u8, mode, "simple")) return;
    if (std.mem.count(u8, execute, ".ArrayList(state_type_") != 1) return error.MissingFrameValueBuffer;

    const loop = std.mem.indexOf(u8, execute, "while (").?;
    const open = std.mem.indexOfScalarPos(u8, execute, loop, '{') orelse return error.MissingLoopBody;
    var depth: usize = 1;
    var end = open + 1;

    while (end < execute.len and depth > 0) : (end += 1) {
        if (execute[end] == '{') depth += 1;
        if (execute[end] == '}') depth -= 1;
    }

    if (depth != 0) return error.UnclosedLoopBody;
    if (std.mem.indexOf(u8, execute[open + 1 .. end - 1], "(allocator).create(") != null) return error.PerIterationFrameBox;
}
